#define ALVR_OXR_BUTTON_SYSTEM_CLICK (1 << 9)

#define ALVR_OXR_BUTTON_THUMBSTICK_CLICK (1 << 10)

#define ALVR_OXR_BUTTON_THUMBSTICK_TOUCH (1 << 11)

#define ALVR_OXR_BUTTON_TRIGGER_CLICK (1 << 12)

