/**
 * Pose returned by the bridge. Coordinate convention follows OpenXR
 * (right-handed, +Y up, -Z forward).
 */
typedef struct AlvrOxrPose {
  float position[3];
  float orientation[4];
} AlvrOxrPose;

/**
 * Per-view static parameters: the eye-to-head pose offset and the
 * per-view field of view, both in OpenXR conventions (radians for FOV,
 * right-handed +Y up -Z forward for the pose). `fov_radians` is
 * `[left, right, up, down]` to match [`AlvrOxrLayer::fov_radians`].
 *
 * These come from the client's reported view configuration and arrive
 * on `ServerCoreEvent::LocalViewParams`. The bridge caches them in a
 * global so [`alvr_oxr_get_view_params`] can return them synchronously
 * — Monado's `xrLocateViews` equivalent calls into us once per frame
 * and shouldn't block on the connection thread.
 */
typedef struct AlvrOxrViewParams {
  struct AlvrOxrPose pose;
  float fov_radians[4];
} AlvrOxrViewParams;

/**
 * Per-frame controller state passed back over the bridge. Buttons and
 * analogue values mirror the OpenXR Touch profile layout.
 */
typedef struct AlvrOxrControllerState {
  struct AlvrOxrPose pose;
  float linear_velocity[3];
  float angular_velocity[3];
  float trigger;
  float squeeze;
  float thumbstick[2];
  uint32_t buttons;
} AlvrOxrControllerState;

/**
 * Haptic pulse parameters. Maps onto OpenXR `XrHapticVibration`.
 */
typedef struct AlvrOxrHaptic {
  int64_t duration_ns;
  float frequency_hz;
  float amplitude;
} AlvrOxrHaptic;

/**
 * One submitted OpenXR composition layer. The Monado-side compositor builds
 * an array of these and hands them to the bridge once per frame.
 *
 * Image handles are platform-specific:
 * * Windows: `HANDLE` from a `D3D11_RESOURCE_MISC_SHARED_NTHANDLE` resource
 *   or `VK_EXTERNAL_MEMORY_HANDLE_TYPE_OPAQUE_WIN32` (`u64` of the HANDLE).
 * * Linux: DMABUF fd (cast to `u64`).
 */
typedef struct AlvrOxrLayer {
  uint32_t layer_type;
  uint32_t view_count;
  uint64_t image_handles[2];
  uint32_t width;
  uint32_t height;
  float fov_radians[4];
  struct AlvrOxrPose pose;
} AlvrOxrLayer;

typedef struct AlvrOxrEvent {
  AlvrOxrEventType event_type;
  int64_t timestamp_ns;
  int32_t data[4];
} AlvrOxrEvent;

